/* Conversation-first prototype. All reasoning below is explicitly simulated locally. */
document.body.classList.add('agent-mode');let mapTab='all';state.agentMessages=Array.isArray(state.agentMessages)?state.agentMessages:[];state.agentProposals=state.agentProposals||{};const norm=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d');const datePlus=n=>{const d=new Date(today+'T12:00:00Z');d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10)};const aTime=()=>new Intl.DateTimeFormat('vi-VN',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Bangkok'}).format(new Date());function aId(){return Date.now().toString(36)+Math.random().toString(36).slice(2,6)}function dateLabel(d){return !d?'Chưa chốt ngày':d===today?'Hôm nay':d===datePlus(1)?'Ngày mai':d.split('-').reverse().slice(0,2).join('/')}function aSave(){save()}function aShowMap(){document.body.classList.toggle('show-map')}function aMap(){const tasks=state.tasks.filter(t=>mapTab==='all'||(mapTab==='work'?workcats:categories).some(c=>c.id===t.category)),pending=tasks.filter(t=>!t.done),waiting=Object.values(state.agentProposals).filter(p=>p.status==='pending').length;const groups=[['work','briefcase','Công việc',workcats],['life','heart','Cuộc sống',categories]].filter(g=>mapTab==='all'||mapTab===g[0]);$('#amap').innerHTML=`<div class="map-heading"><h2>${icon('grid')}Bản đồ của bạn</h2><span class="map-live"><i></i>Theo cuộc trò chuyện</span><button class="map-toggle" data-mapclose="yes" aria-label="Đóng map">${icon('close')}</button></div><p class="map-description">Chỉ cần nhìn để biết mọi thứ đang ở đâu.<br>Cứ nói với Orbit để thay đổi.</p><div class="map-switch"><button class="${mapTab==='all'?'active':''}" data-map="all">Toàn cảnh</button><button class="${mapTab==='work'?'active':''}" data-map="work">Công việc</button><button class="${mapTab==='life'?'active':''}" data-map="life">Cuộc sống</button></div><div class="map-summary"><div class="map-stat"><strong>${String(pending.length).padStart(2,'0')}</strong><span>đang cần làm</span></div><div class="map-stat"><strong>${String(tasks.filter(t=>t.done).length).padStart(2,'0')}</strong><span>đã hoàn thành</span></div><div class="map-stat"><strong>${String(waiting).padStart(2,'0')}</strong><span>chờ bạn chốt</span></div></div><div class="map-section-label">NHỮNG GÌ ĐANG CHẠY <span>${pending.length} việc đang mở</span></div>${groups.map(([id,i,title,cats])=>{const items=tasks.filter(t=>cats.some(c=>c.id===t.category));return `<section class="map-group"><div class="map-group-heading">${icon(i)}${title}<span>${items.filter(t=>!t.done).length} đang chờ</span></div>${items.length?items.slice().sort((a,b)=>Number(a.done)-Number(b.done)).map(t=>`<div class="map-task ${t.done?'done':''}"><span class="map-task-dot"></span><div><div class="map-task-title">${esc(t.title)}</div><div class="map-task-date"><span class="category-dot" style="--color:${cat(t.category).color}"></span>${cat(t.category).name}<span>·</span>${esc(dateLabel(t.date))}${t.time?' · '+esc(t.time):''}</div></div></div>`).join(''):'<div class="map-empty">Chưa có việc nào. Orbit sẽ ghi lại khi bạn chốt.</div>'}</section>`}).join('')}<div class="map-section-label">ĐIỀU BẠN ĐANG HƯỚNG TỚI <span>02 mục tiêu mẫu</span></div><div class="map-goal"><strong>Tiếng Anh tự tin hơn</strong><p>${state.lessons}/20 buổi học · ${Math.min(100,Math.round(state.lessons/20*100))}%</p><div class="bar"><i style="width:${Math.min(100,state.lessons/20*100)}%;background:#b1a6ca"></i></div></div><div class="map-goal"><strong>Quỹ du lịch Nhật Bản</strong><p>${money(state.savings)} / 30.000.000 ₫</p><div class="bar"><i style="width:${Math.min(100,state.savings/30000000*100)}%;background:#a5b794"></i></div></div><div class="map-tip">${icon('spark')}Thử nói “Dời việc học tiếng Anh sang mai” hoặc “Tao xong phần content rồi”. Orbit sẽ đưa thay đổi cho bạn chốt.</div><div class="map-foot">Dữ liệu mẫu + việc bạn đã chốt.<br>Lưu trên trình duyệt · Chưa kết nối app bên ngoài.</div>`}function proposalHTML(id){const p=state.agentProposals[id];if(!p)return '';const pending=p.status==='pending';return `<div class="proposal"><div class="proposal-head"><span>${icon('spark')}${pending?'Mình đề xuất cập nhật như này':'Cập nhật bản đồ'}</span><span class="proposal-status">${pending?'CHỜ BẠN CHỐT':p.status==='applied'?'ĐÃ GHI NHẬN':p.status==='undone'?'ĐÃ HOÀN TÁC':'ĐÃ BỎ QUA'}</span></div>${p.actions.map(a=>`<div class="proposal-row">${icon(a.type==='complete'?'checksquare':a.type==='move'?'calendar':a.type==='note'?'note':a.type==='delete'?'trash':'plus')}<div><strong>${esc(a.label||a.title)}</strong><small>${esc(a.meta||'')}</small></div></div>`).join('')}${pending?`<div class="proposal-actions"><button class="button primary" data-approve="${id}">${icon('check')}Chốt & cập nhật map</button><button class="button secondary" data-reject="${id}">Để sau</button><span>${p.actions.length} thay đổi</span></div>`:`<div class="proposal-result ${p.status==='applied'?'':'proposal-rejected'}">${icon(p.status==='applied'?'check':'clock')}${p.status==='applied'?'Đã cập nhật map bên cạnh.':p.status==='undone'?'Đã trả về trước thay đổi này.':'Chưa thay đổi dữ liệu của bạn.'}${p.status==='applied'&&state.agentLastApplied===id?`<button data-undo="${id}">Hoàn tác</button>`:''}</div>`}</div>`}function welcome(){return `<div class="agent-message"><span class="message-face">✳</span><div class="message-body"><div class="message-meta">Orbit <time>Ở đây cùng bạn</time></div><h2 class="welcome-heading">Bạn cứ nói.<br><em>Mình cùng gỡ từng việc.</em></h2><p class="welcome-description">Việc cần làm, một mục tiêu mới, hay cả đống thứ đang ở trong đầu — cứ kể mình nghe. Mình sẽ giúp gom lại, còn bạn chỉ cần chốt điều muốn làm.</p><div class="welcome-steps"><span class="welcome-step"><b>1</b>Bạn kể</span><span class="welcome-step"><b>2</b>Mình sắp xếp</span><span class="welcome-step"><b>3</b>Bạn chốt, map tự cập nhật</span></div><div class="example-prompts"><button class="example-prompt" data-say="Tuần này tao cần viết 10 bài content, tập lại 3 buổi và tiết kiệm 3 triệu.">${icon('note')}<div><strong>Đang có một đống thứ trong đầu</strong><span>10 bài content, tập lại, tiết kiệm…</span></div></button><button class="example-prompt" data-say="Hôm nay tao nên tập trung vào việc gì?">${icon('sun')}<div><strong>Giúp tao nhìn rõ hôm nay</strong><span>Chọn việc nào để bắt đầu?</span></div></button><button class="example-prompt" data-say="Dời việc học tiếng Anh sang mai">${icon('calendar')}<div><strong>Kế hoạch có chút thay đổi</strong><span>Dời việc học tiếng Anh sang mai</span></div></button><button class="example-prompt" data-say="Tao xong phần content rồi">${icon('checksquare')}<div><strong>Báo một việc vừa xong</strong><span>Tao xong phần content rồi</span></div></button></div></div></div>`}function aFeed(scroll=true){$('#athreadcontent').innerHTML=`<div class="thread-date">Cuộc trò chuyện của bạn · Lưu trên thiết bị này</div>${welcome()}${state.agentMessages.map(m=>m.role==='user'?`<div class="user-message"><div class="user-bubble">${esc(m.text)}</div><time>${esc(m.time)}</time></div>`:`<div class="agent-message"><span class="message-face">✳</span><div class="message-body"><div class="message-meta">Orbit <time>${esc(m.time)}</time></div><div class="message-text">${esc(m.text)}</div>${m.proposal?proposalHTML(m.proposal):''}${m.reference?`<div class="map-reference">${icon('grid')}${esc(m.reference)}</div>`:''}${m.options?m.options.map(o=>`<button class="quick-action" data-say="${esc(o)}">${esc(o)}</button>`).join(' '):''}</div></div>`).join('')}`;if(scroll)setTimeout(()=>{$('#athread').scrollTop=$('#athread').scrollHeight},30);$('#acontext').innerHTML=icon('lock')+(state.agentMessages.length?'Giữ mạch trao đổi trên trình duyệt này · '+state.agentMessages.filter(m=>m.role==='user').length+' lời nhắn':'Một cuộc trò chuyện, cả công việc lẫn cuộc sống')}function aMessage(text,extra={}){state.agentMessages.push({role:'assistant',text,time:aTime(),...extra});aSave();aFeed();aMap()}function aPropose(text,actions){const id=aId();state.agentProposals[id]={status:'pending',actions};aMessage(text,{proposal:id,reference:'Chỉ cập nhật dữ liệu sau khi bạn chốt.'})}function matchTask(q){const stop=new Set('tao toi minh da roi xong phan viec lam nhe nha giup hay cho hoan thanh doi dời sang ngay mai tuan nay cua mot het bao voi bo xoa lich can toi muon'.split(' '));const tokens=norm(q).replace(/[^a-z0-9 ]/g,' ').split(/\s+/).filter(w=>w.length>1&&!stop.has(w));const scored=state.tasks.filter(t=>!t.done).map(t=>{const words=norm(t.title+' '+cat(t.category).name).split(/\s+/);return {t,score:tokens.filter(w=>words.includes(w)).length}}).filter(x=>x.score>0).sort((a,b)=>b.score-a.score);if(!scored.length)return [];return scored.filter(x=>x.score===scored[0].score).map(x=>x.t)}function categoryFor(q){const s=norm(q);if(/content|bai viet|khach|bao gia/.test(s))return 'content';if(/zalo|bot/.test(s))return 'bots';if(/hoc|tieng anh|doc sach|khoa hoc/.test(s))return 'learn';if(/tap|gym|yoga|suc khoe|kham|chay bo/.test(s))return 'health';if(/tiet kiem|tien|quy|chi tieu/.test(s))return 'money';if(/du lich|dat ve|nhat ban|khach san/.test(s))return 'travel';if(/mua|sam/.test(s))return 'shopping';return 'daily'}function scheduleFor(q){const s=norm(q);if(/ngay mai|sang mai/.test(s))return datePlus(1);if(/tuan sau/.test(s))return datePlus(7);if(/hom nay|toi nay|chieu nay|sang nay/.test(s))return today;return ''}function taskAction(title,category,date='',extra=''){return {type:'add',title,category,date,label:title,meta:cat(category).name+' · '+dateLabel(date)+(extra?' · '+extra:'')}}function aApprove(id){const p=state.agentProposals[id];if(!p||p.status!=='pending')return;const invalid=p.actions.some(a=>['complete','move','delete'].includes(a.type)&&!state.tasks.some(t=>t.id===a.taskId));if(invalid){toast('Một việc đã thay đổi. Kể lại cho Orbit để đề xuất lại nhé.');return}p.undo=[];p.actions.forEach(a=>{if(a.type==='add'){const t={id:Date.now()+Math.random(),title:a.title,category:a.category,date:a.date||'',time:'',done:false};state.tasks.push(t);p.undo.push({type:'remove',id:t.id})}else if(a.type==='note'){const n={id:Date.now()+Math.random(),title:a.title,body:a.body,category:a.category};state.notes.unshift(n);p.undo.push({type:'removeNote',id:n.id})}else{const t=state.tasks.find(t=>t.id===a.taskId);p.undo.push({type:'restore',task:{...t}});if(a.type==='complete')t.done=true;if(a.type==='move')t.date=a.date;if(a.type==='delete')state.tasks=state.tasks.filter(t=>t.id!==a.taskId)}});p.status='applied';state.agentLastApplied=id;aSave();aFeed(false);aMap();$('#amap').classList.remove('changed-map');requestAnimationFrame(()=>$('#amap').classList.add('changed-map'));toast('Đã chốt. Map đã cập nhật theo cuộc trao đổi.')}function aUndo(id){const p=state.agentProposals[id];if(!p||p.status!=='applied'||state.agentLastApplied!==id)return;p.undo.slice().reverse().forEach(u=>{if(u.type==='remove')state.tasks=state.tasks.filter(t=>t.id!==u.id);if(u.type==='removeNote')state.notes=state.notes.filter(n=>n.id!==u.id);if(u.type==='restore'){const i=state.tasks.findIndex(t=>t.id===u.task.id);if(i===-1)state.tasks.push(u.task);else state.tasks[i]=u.task}});p.status='undone';state.agentLastApplied=null;aSave();aFeed(false);aMap();toast('Đã hoàn tác thay đổi vừa rồi.')}function aProcess(q){const s=norm(q);if(/^(chot|dong y|ok|duyet|lam di|chot di|oke|ok chot)[.!\s]*$/.test(s)){const entry=Object.entries(state.agentProposals).reverse().find(([id,p])=>p.status==='pending');if(entry){aApprove(entry[0]);aMessage('Đã chốt đề xuất gần nhất. Những thay đổi đã có trên map, bạn cứ kể tiếp nhé.')}else aMessage('Hiện không có đề xuất nào đang chờ chốt. Bạn đang muốn làm việc gì tiếp?');return}if(/^(bo qua|de sau|thoi|huy)[.!\s]*$/.test(s)){const entry=Object.entries(state.agentProposals).reverse().find(([id,p])=>p.status==='pending');if(entry){entry[1].status='rejected';aMessage('Mình để đề xuất đó lại, dữ liệu vẫn giữ nguyên.')}else aMessage('Được, mình dừng ở đây. Khi nào có điều mới bạn cứ kể.');return}if(/hoan tac/.test(s)){if(state.agentLastApplied){aUndo(state.agentLastApplied);aMessage('Đã hoàn tác lần cập nhật gần nhất.')}else aMessage('Chưa có cập nhật nào để hoàn tác.');return}if(/hoan thanh|xong|da lam/.test(s)&&!/can lam|phai lam/.test(s)){const matches=matchTask(q);if(matches.length===1){const t=matches[0];aPropose('Xong thêm một việc, nhẹ đầu hơn rồi. Mình hiểu bạn đang nói đến việc này — đúng thì chốt nhé.',[{type:'complete',taskId:t.id,label:'Hoàn thành: '+t.title,meta:cat(t.category).name+' · Đánh dấu đã xong'}])}else if(matches.length>1)aMessage('Có vài việc khớp với lời bạn nói. Bạn muốn đánh dấu việc nào?',{options:matches.slice(0,4).map(t=>'Xong: '+t.title)});else aMessage('Mình chưa tìm được việc đang mở khớp với lời bạn nói. Bạn nhắc tên việc cụ thể giúp mình nhé; các việc đã chốt đang ở map bên cạnh.');return}if(/\bdoi\b|\bhoan\b|\bdời\b/.test(s)&&/mai|ngay|tuan/.test(s)){const matches=matchTask(q),date=scheduleFor(q);if(!date){aMessage('Bạn muốn dời sang ngày nào? Bản thử hiện hiểu “ngày mai” và “tuần sau”.',{options:['Dời việc học tiếng Anh sang mai']});return}if(matches.length===1){const t=matches[0];aPropose('Mình đề xuất dời việc này để lịch của bạn thoáng hơn. Chốt xong map sẽ cập nhật ngày mới.',[{type:'move',taskId:t.id,date,label:'Dời: '+t.title,meta:dateLabel(t.date)+' → '+dateLabel(date)}])}else if(matches.length>1)aMessage('Bạn muốn dời việc nào? Mình chưa chọn thay bạn nhé.',{options:matches.slice(0,3).map(t=>'Dời '+t.title+' sang mai')});else aMessage('Mình chưa tìm thấy việc bạn muốn dời. Bạn nhắc tên một việc trên map và ngày mới nhé.');return}if(/\bxoa\b|\bbo viec\b/.test(s)){const matches=matchTask(q);if(matches.length===1){const t=matches[0];aPropose('Mình sẽ bỏ việc này khỏi map khi bạn chốt.',[{type:'delete',taskId:t.id,label:'Bỏ việc: '+t.title,meta:cat(t.category).name}])}else aMessage('Bạn muốn bỏ việc nào? Nhắc rõ tên việc trên map để mình chọn đúng nhé.');return}if(/hom nay.*(gi|lo|lam)|uu tien|tap trung|nhin.*(map|viec)|tong hop|co gi|con.*viec/.test(s)){const tasks=state.tasks.filter(t=>!t.done),due=tasks.filter(t=>t.date&&t.date<=today),top=(due.length?due:tasks).slice(0,3);aMessage(top.length?'Mình thấy '+tasks.length+' việc đang mở, trong đó '+due.length+' việc đến hạn hôm nay hoặc trước đó. Có thể bắt đầu như này:\n\n'+top.map((t,i)=>(i+1)+'. '+t.title+' — '+cat(t.category).name).join('\n')+'\n\nĐây là thứ tự gợi ý theo hạn trong dữ liệu demo, chưa phải đánh giá độ quan trọng của AI. Bạn muốn bắt đầu việc nào?':'Hiện không có việc đang mở. Bạn có thể dành một khoảng nghỉ, hoặc kể một điều đang muốn làm.',{reference:'Map đang phản ánh '+tasks.length+' việc chưa hoàn thành.'});return}if(/nho gi|da noi|vua noi|truoc do|mach/.test(s)){const past=state.agentMessages.filter(m=>m.role==='user').slice(0,-1).slice(-3);aMessage(past.length?'Mình đang giữ những lời bạn vừa trao đổi:\n\n'+past.map(m=>'• '+m.text).join('\n')+'\n\nNhững đề xuất đã chốt được lưu thành việc riêng, không chỉ nằm trong hội thoại.':'Mình chưa có lời nhắn trước đó. Bạn cứ kể từ điều đang vướng nhất nhé.');return}if(/duoi|met|qua tai|giam bot|nhieu qua/.test(s)){const tasks=state.tasks.filter(t=>!t.done);aMessage('Vậy mình đừng nhét thêm việc vội. Bạn đang có '+tasks.length+' việc mở. Trong bản thử này, mình có thể giúp dời một việc chưa gấp — bạn chọn việc nào nhé.',{options:tasks.slice(0,3).map(t=>'Dời '+t.title+' sang mai')});return}if(/^(chao|hello|hi|hey|alo)[! .]*$/.test(s)){aMessage('Mình đây. Công việc hay chuyện riêng, hôm nay điều gì đang chiếm chỗ trong đầu bạn?');return}if(/^(cam on|thanks|oke|ok|duoc)[! .]*$/.test(s)){aMessage('Ừ, mình ở đây. Có việc mới hoặc đổi kế hoạch thì cứ nói tiếp nhé.');return}const date=scheduleFor(q);if(/ghi nho|nho ho|ghi lai/.test(s)&&!/(can|phai|nhac|viec)/.test(s)){const title=q.replace(/^(ghi nhớ|nhớ hộ|ghi lại)[\s:,-]*/i,'').trim()||q;aPropose('Mình sẽ giữ lại như một ghi nhớ, không biến thành việc cần làm.',[{type:'note',title:title.slice(0,100),body:q,category:categoryFor(q),label:'Ghi nhớ: '+title,meta:'Ghi nhớ cá nhân · Lưu trên trình duyệt'}]);return}const actions=[];if(/content|bai viet/.test(s)){const count=s.match(/(\d+)\s*bai/);actions.push(taskAction(count?'Viết '+count[1]+' bài content'+(/tuan nay/.test(s)?' tuần này':''):q.replace(/^(tao|toi|minh)\s*/i,'').trim(),'content',date,/tuan nay/.test(s)?'Chưa chốt hạn cụ thể':''))}if(/tap|gym|yoga|chay bo/.test(s)){const count=s.match(/(\d+)\s*buoi/);actions.push(taskAction(count?'Tập luyện '+count[1]+' buổi'+(/tuan/.test(s)?' trong tuần':''):'Dành thời gian tập luyện','health',date))}if(/tiet kiem/.test(s)){const amt=s.match(/(\d+(?:[.,]\d+)?)\s*(trieu|tr|k|nghin)/);actions.push(taskAction('Dành '+(amt?amt[1]+' '+(amt[2]==='tr'?'triệu':amt[2]):'một khoản tiết kiệm')+(/moi thang/.test(s)?' mỗi tháng':''),'money',date,'Chỉ ghi việc, không chuyển tiền'))}if(!actions.length){let title=q.replace(/^(tao|tôi|tui|mình)\s+(muốn|cần|phải)\s+/i,'').replace(/^(nhắc tao|nhắc tôi|nhắc mình|thêm việc)\s*/i,'').trim();title=title.charAt(0).toUpperCase()+title.slice(1);actions.push(taskAction(title,categoryFor(q),date))}const fresh=actions.filter(a=>!state.tasks.some(t=>!t.done&&norm(t.title)===norm(a.title)));if(!fresh.length){aMessage('Việc này đã có trong map, mình không thêm trùng nhé. Bạn muốn dời lịch hay cập nhật việc đó?');return}const intro=fresh.length>1?'Mình gom thành '+fresh.length+' việc, tách công việc và chuyện riêng. Đây mới là đề xuất, bạn xem rồi chốt nhé.':'Mình thử gom lời bạn thành một việc như dưới đây. Nếu chưa đúng ý, bạn có thể để sau rồi diễn đạt lại.';aPropose(intro+(fresh.some(a=>!a.date)?'\n\nNhững việc chưa rõ thời hạn sẽ để “Chưa chốt ngày”, mình không tự gán lịch.':''),fresh)}function aSend(q){q=q.trim().slice(0,3000);if(!q)return;state.agentMessages.push({role:'user',text:q,time:aTime()});$('#acompose').value='';aSave();aFeed();aProcess(q);$('#acompose').focus()}function aInit(){document.querySelector('.app-shell').innerHTML=`<header><div class="breadcrumb"><button class="icon-button mobile-menu" id="amobile" aria-label="Mở menu">${icon('menu')}</button><span>${icon('chat')}</span><span class="crumb-muted">Không gian của mình</span><span class="crumb-divider">/</span><strong>Trò chuyện với Orbit</strong></div><div class="header-actions"><button class="search-button" id="ahistory">${icon('clock')}<span>Lịch sử trao đổi</span></button><span class="header-divider"></span><span class="avatar small-avatar">M</span></div></header><main><div class="agent-layout"><section class="conversation" aria-label="Trò chuyện với agent tổng"><div class="conversation-top"><div class="conversation-id"><span class="agent-face">✳</span><div><h1>Orbit, trợ lý tổng của bạn</h1><p><span class="agent-status"></span>Công việc & cuộc sống, trong cùng một mạch.</p></div></div><div class="conversation-badges"><button class="mode-badge" id="asimulation">MÔ PHỎNG</button><button class="map-toggle" id="amaptoggle">${icon('grid')}<span class="map-label">Xem map</span></button></div></div><div class="thread" id="athread" role="log" aria-label="Lịch sử trò chuyện"><div class="thread-content" id="athreadcontent"></div></div><div class="composer-wrap"><div class="composer-inner"><div class="composer-context" id="acontext"></div><form class="main-composer" id="aform"><textarea id="acompose" rows="2" placeholder="Cứ kể những gì đang ở trong đầu bạn…" aria-label="Nói với Orbit" maxlength="3000"></textarea><div class="composer-controls"><div class="composer-tools">${icon('spark')}Agent tổng<span>·</span>CV + CS<span>·</span>Giữ mạch trao đổi</div><button class="send-main" aria-label="Gửi lời nhắn">${icon('up')}</button></div></form><div class="composer-note"><span>Chốt trong chat, map tự cập nhật. Bạn không cần sắp xếp thủ công.</span><span>Enter để gửi · Shift + Enter xuống dòng</span></div></div></div></section><section class="live-map" id="amap" aria-label="Bản đồ công việc và cuộc sống"></section></div></main>`;$('#mainnav').innerHTML=`<button class="nav-item active" data-agentnav="chat">${icon('chat')}Nói chuyện với Orbit<span class="nav-counter">✳</span></button><button class="nav-item" data-agentnav="today">${icon('sun')}Hôm nay cần lo gì</button><button class="nav-item" data-agentnav="history">${icon('clock')}Lịch sử trao đổi</button>`;$('.areas-label').innerHTML='BẢN ĐỒ CỦA BẠN';$('#areanav').innerHTML=`<button class="nav-item" data-agentnav="mapall">${icon('grid')}Toàn cảnh</button><button class="nav-item" data-agentnav="mapwork">${icon('briefcase')}Công việc</button><button class="nav-item" data-agentnav="maplife">${icon('heart')}Cuộc sống</button><div class="agent-nav-note">Không cần mở từng mục.<br>Cứ nói, Orbit sẽ giúp bạn gom lại.</div>`;$('.brand').onclick=e=>{e.preventDefault();$('#athread').scrollTop=0;document.body.classList.remove('sidebar-open')};$('#amobile').onclick=()=>document.body.classList.toggle('sidebar-open');$('#aform').onsubmit=e=>{e.preventDefault();aSend($('#acompose').value)};$('#acompose').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();aSend($('#acompose').value)}};$('#amaptoggle').onclick=aShowMap;$('#asimulation').onclick=()=>showModal('Thử cách dùng trước, nối AI sau',`<div class="modal-detail">Bản này dùng quy tắc minh họa để thử luồng: bạn nói → agent đề xuất → bạn chốt → map cập nhật.<br><br>Bạn có thể thử thêm việc, báo xong, dời sang ngày mai, hỏi ưu tiên và hoàn tác. Những câu ngoài phạm vi sẽ được đề xuất thành việc để bạn kiểm tra.<br><br>Chưa gọi Claude/GPT, chưa truy cập app thật, chưa gửi nhắc việc. Lịch sử và dữ liệu được lưu trên trình duyệt này.</div>`);$('#ahistory').onclick=aHistory;aFeed(false);aMap()}function aHistory(){const messages=state.agentMessages.filter(m=>m.role==='user');showModal('Lịch sử trao đổi',messages.length?`<div class="calendar-list">${messages.slice().reverse().map(m=>`<div class="calendar-entry"><span class="date-box">${esc(m.time)}</span><div><strong>${esc(m.text)}</strong></div></div>`).join('')}</div><p class="modal-info">Lưu trên trình duyệt này. Đóng cửa sổ để tiếp tục cùng mạch trao đổi.</p>`:'<div class="empty-state">Chưa có lời nhắn nào. Kể cho Orbit một việc bạn muốn làm nhé.</div>')}document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.say)aSend(b.dataset.say);if(b.dataset.approve)aApprove(b.dataset.approve);if(b.dataset.reject){const p=state.agentProposals[b.dataset.reject];if(p&&p.status==='pending'){p.status='rejected';aSave();aFeed(false);aMap();toast('Để sau nhé. Map chưa thay đổi.')}}if(b.dataset.undo)aUndo(b.dataset.undo);if(b.dataset.mapclose)document.body.classList.remove('show-map');if(b.dataset.map){mapTab=b.dataset.map;aMap()}if(b.dataset.agentnav){const n=b.dataset.agentnav;document.body.classList.remove('sidebar-open');if(n==='chat')$('#acompose').focus();if(n==='today')aSend('Hôm nay tao nên tập trung vào việc gì?');if(n==='history')aHistory();if(n.startsWith('map')){mapTab=n==='mapwork'?'work':n==='maplife'?'life':'all';aMap();if(window.innerWidth<=970)document.body.classList.add('show-map')}}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();e.stopImmediatePropagation();$('#acompose').focus()}if(e.key==='Escape')document.body.classList.remove('show-map')},true);aInit();
